using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;

    /// <summary>
    /// Maximum number of sentences in the summary. Defaults to 3.
    /// </summary>
    [Range(1, 20)]
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

using DocSummary.Models;

namespace DocSummary.Services;

public class DocumentSummarizationService
{
    private static readonly char[] SentenceTerminators = ['.', '!', '?'];

    public SummarizeResponse Summarize(string documentText, int maxSentences)
    {
        var sentences = SplitIntoSentences(documentText);

        if (sentences.Count <= maxSentences)
        {
            var fullText = string.Join(" ", sentences);
            return new SummarizeResponse
            {
                Summary = fullText,
                OriginalLength = documentText.Length,
                SummaryLength = fullText.Length
            };
        }

        var scored = ScoreSentences(sentences);
        var topSentences = scored
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => s.Index)
            .Select(s => s.Sentence);

        var summary = string.Join(" ", topSentences);

        return new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = documentText.Length,
            SummaryLength = summary.Length
        };
    }

    private static List<string> SplitIntoSentences(string text)
    {
        var sentences = new List<string>();
        int start = 0;

        for (int i = 0; i < text.Length; i++)
        {
            if (SentenceTerminators.Contains(text[i]))
            {
                // Include the terminator, skip trailing whitespace
                var sentence = text[start..(i + 1)].Trim();
                if (sentence.Length > 0)
                    sentences.Add(sentence);
                start = i + 1;
            }
        }

        // Capture any trailing text without a terminator
        var remaining = text[start..].Trim();
        if (remaining.Length > 0)
            sentences.Add(remaining);

        return sentences;
    }

    private static List<ScoredSentence> ScoreSentences(List<string> sentences)
    {
        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        foreach (var sentence in sentences)
        {
            foreach (var word in GetWords(sentence))
            {
                wordFrequency.TryGetValue(word, out int count);
                wordFrequency[word] = count + 1;
            }
        }

        var scored = new List<ScoredSentence>();
        for (int i = 0; i < sentences.Count; i++)
        {
            var words = GetWords(sentences[i]);
            double score = words.Length > 0
                ? words.Sum(w => wordFrequency.GetValueOrDefault(w, 0)) / (double)words.Length
                : 0;

            // Boost earlier sentences slightly (positional bias)
            score *= 1.0 + (1.0 / (i + 1));

            scored.Add(new ScoredSentence(i, sentences[i], score));
        }

        return scored;
    }

    private static string[] GetWords(string sentence) =>
        sentence.Split([' ', '\t', '\n', '\r'], StringSplitOptions.RemoveEmptyEntries)
                .Select(w => w.Trim('.', ',', '!', '?', ';', ':', '"', '\'', '(', ')'))
                .Where(w => w.Length > 2)
                .ToArray();

    private sealed record ScoredSentence(int Index, string Sentence, double Score);
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly DocumentSummarizationService _summarizationService;

    public SummarizeController(DocumentSummarizationService summarizationService)
    {
        _summarizationService = summarizationService;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        var result = _summarizationService.Summarize(request.DocumentText, request.MaxSentences);
        return Ok(result);
    }
}

